#include <cstdio>
#include <cstring>
#include <queue>
#include <vector>
#include <algorithm>
#include <array>
using namespace std;

const int INF = 0x3f3f3f3f;
const int LIM = 202;
array<array<int, LIM>, LIM> cap{};
array<array<int, LIM>, LIM> flo{};

int n, t, zi, zj;
char a[11][11], b[11][11];
vector<vector<int> > mat;
int dx[4] = {1, -1, 0, 0};
int dy[4] = {0, 0, 1, -1};

int maxflow(int N, int S, int T) {
    vector<int> pre(N), d(N);
    while (true) {
        fill(pre.begin(), pre.end(), -1);
        queue<int> q;
        pre[S] = S;
        d[S] = INF;
        q.push(S);
        while (!q.empty() && pre[T] == -1) {
            int u = q.front(); q.pop();
            for (int v = 0; v < N; ++v) {
                int rem = cap[u][v] - flo[u][v];
                if (pre[v] == -1 && rem > 0) {
                    pre[v] = u;
                    d[v] = min(d[u], rem);
                    q.push(v);
                }
            }
        }
        if (pre[T] == -1) break;
        for (int v = T; v != S; v = pre[v]) {
            int u = pre[v];
            flo[u][v] += d[T];
            flo[v][u] -= d[T];
        }
    }
    int ans = 0;
    for (int i = 0; i < N; ++i) ans += flo[S][i];
    return ans;
}

int main() {
    scanf("%d%d", &n, &t);
    for (int i = 0; i < n; ++i) scanf("%s", a[i]);
    for (int i = 0; i < n; ++i) scanf("%s", b[i]);
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (a[i][j] == 'Z') zi = i, zj = j;

    mat.assign(n * n, vector<int>(n * n, INF));

    auto bfs = [&](int A, int B, bool check) {
        int src = A * n + B;
        vector<int>& vis = mat[src];
        queue<pair<int, int> > q;
        vis[src] = 0;
        q.push(make_pair(A, B));
        while (!q.empty()) {
            pair<int, int> cur = q.front(); q.pop();
            int p = cur.first * n + cur.second;
            int dis = vis[p];
            if (check && (mat[zi * n + zj][p] <= dis || t <= dis)) {
                if (mat[zi * n + zj][p] < dis || t < dis) vis[p] = INF + 1;
                continue;
            }
            for (int d = 0; d < 4; ++d) {
                int ni = cur.first + dx[d];
                int nj = cur.second + dy[d];
                if (ni < 0 || nj < 0 || ni == n || nj == n) continue;
                if (b[ni][nj] < '0' || b[ni][nj] > '9') continue;
                int nxt = ni * n + nj;
                if (vis[nxt] != INF) continue;
                vis[nxt] = dis + 1;
                q.push(make_pair(ni, nj));
            }
        }
    };

    bfs(zi, zj, false);
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (a[i][j] >= '1' && a[i][j] <= '9') bfs(i, j, true);

    vector<int> targets;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (b[i][j] <= '0' || b[i][j] > '9') continue;
            int p = i * n + j;
            targets.push_back(p);
            cap[p + 2 + n * n][1] = b[i][j] - '0';
        }
    }
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (a[i][j] <= '0' || a[i][j] > '9') continue;
            int p = i * n + j;
            cap[0][p + 2] = a[i][j] - '0';
            for (int k = 0; k < (int)targets.size(); ++k) {
                int q = targets[k];
                if (mat[p][q] < INF) cap[p + 2][q + 2 + n * n] = INF;
            }
        }
    }

    printf("%d\n", maxflow(2 + n * n + n * n, 0, 1));
    return 0;
}
